import{_ as u,a0 as a,w as i,s as l,ao as s,I as n,x as r,a1 as p,A as e}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const h=JSON.parse('{"title":"Linux有问必答：如何禁止Ubuntu的Apport内部错误报告程序 | LCTT x X-CMD","titleTemplate":false,"description":"Linux有问必答：如何禁止Ubuntu的Apport内部错误报告程序 | LCTT (201501) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux有问必答：如何禁止Ubuntu的Apport内部错误报告程序 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux有问必答：如何禁止Ubuntu的Apport内部错误报告程序 | LCTT (201501) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201501/20141208 Linux FAQs with Answers--How to disable Apport internal error reporting on Ubuntu","title":"Linux有问必答：如何禁止Ubuntu的Apport内部错误报告程序","tag":"201501","desc":""},"relativePath":"201501/20141208 Linux FAQs with Answers--How to disable Apport internal error reporting on Ubuntu.md","filePath":"[post].md"}'),d={name:"201501/20141208 Linux FAQs with Answers--How to disable Apport internal error reporting on Ubuntu.md"};function b(A,t,m,x,f,T){const o=a("Link");return i(),l("div",null,[t[11]||(t[11]=s(`<h1 id="linux有问必答-如何禁止ubuntu的apport内部错误报告程序" tabindex="-1">Linux有问必答：如何禁止Ubuntu的Apport内部错误报告程序 <a class="header-anchor" href="#linux有问必答-如何禁止ubuntu的apport内部错误报告程序" aria-label="Permalink to “Linux有问必答：如何禁止Ubuntu的Apport内部错误报告程序”">​</a></h1><blockquote><p><strong>问题</strong>：在桌面版Ubuntu中，我经常遇到一些弹窗窗口，警告我Ubuntu发生了内部错误，问我要不要发送错误报告。每次软件崩溃都要烦扰我，我如何才能关掉这个错误报告功能呢？</p></blockquote><p>Ubuntu桌面版预装了Apport，它是一个错误收集系统，会收集软件崩溃、未处理异常和其他，包括程序bug，并为调试目的生成崩溃报告。当一个应用程序崩溃或者出现Bug时候，Apport就会通过弹窗警告用户并且询问用户是否提交崩溃报告。你也许也看到过下面的消息。</p><ul><li>&quot;Sorry, the application XXXX has closed unexpectedly.&quot;</li><li>&quot;对不起，应用程序XXXX意外关闭了。&quot;</li><li>&quot;Sorry, Ubuntu XX.XX has experienced an internal error.&quot;</li><li>&quot;对不起，Ubuntu XX.XX 发生了一个内部错误。&quot;</li><li>&quot;System program problem detected.&quot;</li><li>&quot;检测到系统程序问题。&quot;</li></ul><p><img src="https://farm9.staticflickr.com/8635/15688551119_708b23b12a_z.jpg" alt=""></p><p>也许因为应用一直崩溃，频繁的错误报告会使人心烦。也许你担心Apport会收集和上传你的Ubuntu系统的敏感信息。无论什么原因，你想关掉Apport的错误报告功能。</p><h3 id="临时关闭apport错误报告" tabindex="-1">临时关闭Apport错误报告 <a class="header-anchor" href="#临时关闭apport错误报告" aria-label="Permalink to “临时关闭Apport错误报告”">​</a></h3><p>如果你想要临时关闭Apport，使用下列命令</p><pre><code>$ sudo service apport stop 
</code></pre><p>注意重启Ubuntu系统Apport会继续开启</p><h3 id="永久关闭apport错误报告" tabindex="-1">永久关闭Apport错误报告 <a class="header-anchor" href="#永久关闭apport错误报告" aria-label="Permalink to “永久关闭Apport错误报告”">​</a></h3><p>为了永久关闭Apport，编辑/etc/default/apport，修改下列参数</p><pre><code>enabled=0
</code></pre><p>重启你的Ubuntu系统，Apport将会自动关闭</p><p>如果你再也不会用Apport，有一种简单的方法完全移除它</p><pre><code>$ sudo apt-get purge apport 
</code></pre><hr>`,17)),n("p",null,[t[1]||(t[1]=r("via: ",-1)),p(o,{href:"http://ask.xmodulo.com/disable-apport-internal-error-reporting-ubuntu.html"},{default:e(()=>[...t[0]||(t[0]=[r("http://ask.xmodulo.com/disable-apport-internal-error-reporting-ubuntu.html",-1)])]),_:1})]),n("p",null,[t[4]||(t[4]=r("译者：",-1)),p(o,{href:"http://www.vicyu.net/"},{default:e(()=>[...t[2]||(t[2]=[r("VicYu/Vic020",-1)])]),_:1}),t[5]||(t[5]=r(" 校对：",-1)),p(o,{href:"https://github.com/wxy"},{default:e(()=>[...t[3]||(t[3]=[r("wxy",-1)])]),_:1})]),n("p",null,[t[8]||(t[8]=r("本文由 ",-1)),p(o,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...t[6]||(t[6]=[r("LCTT",-1)])]),_:1}),t[9]||(t[9]=r(" 原创翻译，",-1)),p(o,{href:"http://linux.cn/"},{default:e(()=>[...t[7]||(t[7]=[r("Linux中国",-1)])]),_:1}),t[10]||(t[10]=r(" 荣誉推出",-1))])])}const L=u(d,[["render",b]]);export{h as __pageData,L as default};
